mapper.select:
select isb.*,pro.P_Name as projectName, pro.P_Competent_Department as pCompetentDepartment,sd.D_Name as pCompetentDepartmentName, pro.P_Apply_File as projectApplyFile, pro.P_Approve_budget as pApproveBudget, pro.p_record_amount as pRecordAmount, pro.p_approval_amount as pApprovalAmount, pro.p_project_form_type as pProjectFormType, pro.p_inv_total as pInvTotal from Investment_Estimate_Breakdown isb left join Pre_Project pro on isb.Project_ID = pro.P_ID left join SYS_Department sd on pro.P_Competent_Department = sd.D_ID
${authSql}
where 1=1
and likePname(#{params.projectName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.projectName},'%')
and isb.State = #{params.state}
and isb.Project_ID = #{params.projectId}
order by isb.Create_Time desc

select details.*
from Investment_Estimate_Breakdown_Details details
where details.Isb_ID = #{id}
